/* tslint:disable */
/* eslint-disable */

export interface AlbumTree {
    id: string[];
    title: string[];
    parent_id: (string | null)[];
    _lft: Int32Array;
    _rgt: Int32Array;
}

export interface Augmented {
    prefix: string[];
    trimmedId: string[];
    trimmedParentId: string[];
    isDuplicate_rgt: Uint8Array;
    isDuplicate_lft: Uint8Array;
    isExpectedParentId: Uint8Array;
}

export type AugmentedAlbumTree = AlbumTree & Augmented;

export type ErrorKind =
| "invalid_left"
| "invalid_right"
| "invalid_left_right"
| "duplicate_left"
| "duplicate_right"
| "parent"
| "unknown";

/**
 * Everything a consumer needs to build the translated error message: the
 * `kind` maps 1:1 onto the `fix-tree.errors.<kind>` translation keys used by
 * Lychee's frontend, and `lft`/`rgt`/`parentId` are the interpolation args.
 */
export interface ErrorDescriptor {
    trimmedId: string;
    kind: ErrorKind;
    lft: number;
    rgt: number;
    parentId: string | null;
}

export interface PrepareResult {
    albums: AugmentedAlbumTree;
    errors: ErrorDescriptor[];
    isValid: boolean;
}

export interface ModifiedAlbums {
    id: string[];
    _lft: Int32Array;
    _rgt: Int32Array;
    parent_id: (string | null)[];
}



/**
 * Inverse of [`increment_lft`]: closes the gap left by removing a row at
 * `id`'s `_lft`.
 */
export function decrementLft(albums: AugmentedAlbumTree, id: string): AugmentedAlbumTree;

/**
 * Inverse of [`increment_rgt`]: closes the gap left by removing a row at
 * `id`'s `_rgt`, unless the safety check (`_lft === _rgt - 1`) trips.
 */
export function decrementRgt(albums: AugmentedAlbumTree, id: string): AugmentedAlbumTree;

/**
 * Diffs `current` against `original` by id, returning only the rows whose
 * `_lft`, `_rgt` or `parent_id` changed (plus any row in `current` that
 * isn't in `original` at all, i.e. newly added).
 */
export function getModifiedAlbums(current: AlbumTree, original: AlbumTree): ModifiedAlbums;

/**
 * Shifts every row whose `_lft` is `>= id`'s `_lft` up by one, making room to
 * insert immediately before it.
 */
export function incrementLft(albums: AugmentedAlbumTree, id: string): AugmentedAlbumTree;

/**
 * Shifts every row whose `_rgt` is `>= id`'s `_rgt` up by one, making room to
 * insert immediately after it (as a sibling) or as its first child.
 */
export function incrementRgt(albums: AugmentedAlbumTree, id: string): AugmentedAlbumTree;

/**
 * Validates a tree: builds duplicate `_lft`/`_rgt` sets, walks the tree in
 * `_lft` order tracking a parent stack to flag rows with an unexpected
 * `parent_id`, and classifies every row that fails validation. `source`
 * should already be sorted by `_lft` (the original composable relies on the
 * same precondition), and all of its arrays must have the same length.
 */
export function prepareAlbums(source: AlbumTree): PrepareResult;

/**
 * Sets up better panic messages in the browser/Node console.
 *
 * Optional: call this once at startup. Safe to call more than once.
 */
export function setPanicHook(): void;

export type InitInput = RequestInfo | URL | Response | BufferSource | WebAssembly.Module;

export interface InitOutput {
    readonly memory: WebAssembly.Memory;
    readonly decrementLft: (a: any, b: number, c: number) => [number, number, number];
    readonly decrementRgt: (a: any, b: number, c: number) => [number, number, number];
    readonly getModifiedAlbums: (a: any, b: any) => [number, number, number];
    readonly incrementLft: (a: any, b: number, c: number) => [number, number, number];
    readonly incrementRgt: (a: any, b: number, c: number) => [number, number, number];
    readonly prepareAlbums: (a: any) => [number, number, number];
    readonly setPanicHook: () => void;
    readonly __wbindgen_malloc: (a: number, b: number) => number;
    readonly __wbindgen_realloc: (a: number, b: number, c: number, d: number) => number;
    readonly __wbindgen_free: (a: number, b: number, c: number) => void;
    readonly __wbindgen_exn_store: (a: number) => void;
    readonly __externref_table_alloc: () => number;
    readonly __wbindgen_externrefs: WebAssembly.Table;
    readonly __externref_table_dealloc: (a: number) => void;
    readonly __wbindgen_start: () => void;
}

export type SyncInitInput = BufferSource | WebAssembly.Module;

/**
 * Instantiates the given `module`, which can either be bytes or
 * a precompiled `WebAssembly.Module`.
 *
 * @param {{ module: SyncInitInput }} module - Passing `SyncInitInput` directly is deprecated.
 *
 * @returns {InitOutput}
 */
export function initSync(module: { module: SyncInitInput } | SyncInitInput): InitOutput;

/**
 * If `module_or_path` is {RequestInfo} or {URL}, makes a request and
 * for everything else, calls `WebAssembly.instantiate` directly.
 *
 * @param {{ module_or_path: InitInput | Promise<InitInput> }} module_or_path - Passing `InitInput` directly is deprecated.
 *
 * @returns {Promise<InitOutput>}
 */
export default function __wbg_init (module_or_path?: { module_or_path: InitInput | Promise<InitInput> } | InitInput | Promise<InitInput>): Promise<InitOutput>;
